head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.fn_SetPar;
scwin.fn_GetPar;
scwin.vScrenID = 'ULDFIS00500.xml';
scwin.vSecugrpID = SECUGRP_ID_ST;
scwin.queryId;
scwin.search_ACCNT_PTTN = ""; // 검색시 수정된 유형
scwin.search_IND_PTTN = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 검색시 수정된 업종유형

/**
 *  재무 환경데이터를 조회한다
 */
scwin.fn_InspecOp = function() {
    if ($c.stf.getObjectValue(txb_CoSnm) == "") {
        $c.win.alert("조회 기업을 검색해 주세요");
        txb_CoSnm.focus();
        return false;
    }

    // 분기별
    var queryId = "krx.lds.stf.fis.select.InspecOpValue2";

    // 동기별
    if ($c.stf.getObjectValue(cmb_shType) == "1") scwin.queryId = "krx.lds.stf.fis.select.InspecOpValue";
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + scwin.queryId + "&outputMessageId=FIS_COM_OUT_INSPECOPVALUE" + "&param01=" + $c.stf.getObjectValue(txb_KisCd) + "&param02=" + $c.stf.getObjectValue(cmb_accStand) + "&param03=" + $c.stf.getObjectValue(cmb_setTime) + "&param04=" + $c.stf.getObjectValue(cmb_eachConn) + "&param05=" + $c.stf.getObjectValue(cmb_closing); //결산년도

    dts_inspecOp.DataID = encodeURI(url);
    dts_inspecOp.Reset();
};


/**
 *  재무 데이터를 조회한다
 */
scwin.fn_Search3 = function() {
    $c.cm.ShowWin(grd_ComList);

    // 자본변동표인경우 계정코드가 요약이 없어 재무전체로 변경한다
    if ($c.stf.getObjectValue(cmb_type) == "6") {
        $c.stf.setObjectValue(rdo_TYPE, 2);
    }

    // 제조업일경우 유형을 4(현금흐름표)일경우 6으로 바꿔준다 6(자본변동표)인경우 -> 업종유형을 2로 바꿔준다
    scwin.search_ACCNT_PTTN = $c.stf.getObjectValue(cmb_type);
    scwin.search_IND_PTTN = $c.stf.getObjectValue(txb_IndPttn);
    if (txb_IndPttn.getValue() == "1") {
        if ($c.stf.getObjectValue(cmb_type) == "4") {
            scwin.search_ACCNT_PTTN = "6";
        } else if ($c.stf.getObjectValue(cmb_type) == "6") {
            scwin.search_IND_PTTN = "2";
        }
    }
    if ($c.stf.getObjectValue(cmb_shType) == "1") {
        scwin.queryId = "krx.lds.stf.fis.select.sameTime";
    } else {
        scwin.queryId = "krx.lds.stf.fis.select.finQuarter";
    }

    //alert("queryId="+queryId);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + scwin.queryId + "&outputMessageId=FIS_COM_OUT_STATELIST" + "&param01=" + $c.stf.getObjectValue(txb_KisCd) + "&param02=" + $c.stf.getObjectValue(cmb_closing) + "&param03=" + scwin.search_ACCNT_PTTN + "&param04=" + $c.stf.getObjectValue(cmb_searchType) + "&param05=" + $c.stf.getObjectValue(cmb_unit) + "&param06=" + $c.stf.getObjectValue(cmb_accStand) + "&param07=" + $c.stf.getObjectValue(cmb_eachConn) + "&param08=" + $c.stf.getObjectValue(cmb_setTime) + "&param09=" + $c.stf.getObjectValue(rdo_TYPE) + "&param10=" + scwin.search_IND_PTTN; //년_1

    dts_ComList.DataID = encodeURI(url);
    dts_ComList.Reset();
};



/**
 * 팝업으로 값을 넘김.
 */
scwin.fn_GetParKisCd = function() {
    var arrPar = new Array();
    arrPar[0] = txb_CoSnm.getValue(); // 기업명
    return arrPar;
};

/**
 * 팝업에서 넘어온 값 세팅.
 */
scwin.fn_SetParKisCd = function(arrPar) {
    txb_CoSnm.setValue(arrPar[0].CO_SNM); //기업명
    txb_KisCd.setValue(arrPar[0].KIS_CD); //기업코드


    if ($c.stf.getObjectValue(txb_KisCd) != "") {
        scwin.fn_InspecOp();
    }
};



/**
 * 기업검색 팝업
 */
scwin.fn_ComSrchOpen = async function() {
    await $c.frame.CreateDialogFrame("KIS_CD", "./ULDFIS00100_P1.gfm", "기업 검색", 100, 100, 640 + 20, 445 + 45, "window");
};

/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.
    if ($c.stf.getObjectValue(txb_CoSnm) == "") {
        $c.win.alert("기업명을 입력하세요.");
        txb_CoSnm.focus();
        return false;
    }

    // 기업명은 있는데 기업코드가 없는 경우
    if ($c.stf.getObjectValue(txb_CoSnm) != "" && $c.stf.getObjectValue(txb_KisCd) == "") {
        scwin.fn_ComInfoSrch();
        return false;
    }
    return true;
};

/**
 * 팝업에서 넘어온 값 세팅.
 */
scwin.fn_SetParKisCd = function(arrPar) {
    txb_CoSnm.setValue(arrPar[0].CO_SNM); //기업명
    txb_KisCd.setValue(arrPar[0].KIS_CD); //기업코드		
    txb_IndPttn.setValue(arrPar[0].IND_PTTN);
    if ($c.stf.getObjectValue(txb_KisCd) != "") {
        scwin.fn_InspecOp();
    }
};



/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.fn_OpenDetail = function(v_Currow) {
    if (v_Currow == undefined) {
        v_Currow = dts_ComList.getRowPosition();
    }
    var arrPar = new Array();
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = {
            nm: dts_ComList.getCellData(v_Currow, "nm"), //기업명	
            data_op1_1: dts_ComList.getCellData(v_Currow, "data_op1_1"), //금액1	
            data_op1_2: dts_ComList.getCellData(v_Currow, "data_op1_2"), //구성비1	
            data_op2_1: dts_ComList.getCellData(v_Currow, "data_op2_1"), //금액2	
            data_op2_2: dts_ComList.getCellData(v_Currow, "data_op2_2"), //구성비2	
            data_op3_1: dts_ComList.getCellData(v_Currow, "data_op3_1"), //금액3	
            data_op3_2: dts_ComList.getCellData(v_Currow, "data_op3_2"), //구성비3	
            data_op4_1: dts_ComList.getCellData(v_Currow, "data_op4_1"), //금액4	
            data_op4_2: dts_ComList.getCellData(v_Currow, "data_op4_2") //구성비4
        };
        //fn_SetPar(arrPar);

    }
    // frame.CloseFrame();

};






/**
 * 기업정보 조회(명으로 조회)
 */
scwin.fn_ComInfoSrch = function() {
    //데이터셋 초기화
    dts_ComList.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.comInfo" + "&outputMessageId=FIS_COM_INFO" + "&param01=" + $c.stf.getObjectValue(txb_CoSnm);
    dts_ComInfo.DataID = encodeURI(url);
    dts_ComInfo.Reset();

    // 조회결과가 1개이면 기업개황 조회 아니면 기업팝업 오픈.
    if (dts_ComInfo.getTotalRow() == 1) {
        // 조회조건에 값을 세팅하고..
        txb_KisCd.setValue(dts_ComInfo.getCellData(0, "KIS_CD"));
        txb_IndPttn.setValue(dts_ComInfo.getCellData(0, "IND_PTTN"));
        scwin.fn_InspecOp(); // 기업개황 조회

    } else {
        scwin.fn_ComSrchOpen(); //기업검색 팝업 오픈

    }
};



/**
 * 결산연도를 가져온다
 */
scwin.fn_firstSet = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.SettlementOfAccountsValue" + "&outputMessageId=FIS_COM_OUT_SETOFACCVALUE";
    dts_AcntclsDt.DataID = encodeURI(url);
    dts_AcntclsDt.Reset();
    scwin.fn_initialize();
};


/**
 * 상단 HEADER 부분 초기화
 */
scwin.fn_initialize = function() {
    $c.cm.setColumnProp(grd_ComList, "1date", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "2date", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "3date", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "4date", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "inspection1", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "inspection2", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "inspection3", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "inspection4", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op1_2", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op2_2", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op3_2", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op4_2", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op1_1", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op2_1", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op3_1", "Name", "");
    $c.cm.setColumnProp(grd_ComList, "data_op4_1", "Name", "");
};


/**
 * 감사의견 세팅
 */
scwin.getOpiText = function(opiCode) {
    var opiText = "";
    if (opiCode == "10") opiText = "적정";
    if (opiCode == "20") opiText = "한정";
    if (opiCode == "21") opiText = "한정-감사범위제한";
    if (opiCode == "22") opiText = "한정-기업회계기준위배";
    if (opiCode == "30") opiText = "부적정";
    if (opiCode == "31") opiText = "부적정 -계속기업존속의문시";
    if (opiCode == "40") opiText = "의견거절";
    if (opiCode == "41") opiText = "의견거절-독립성결";
    if (opiCode == "42") opiText = "의견거절-감사범위제한";
    if (opiCode == "43") opiText = "의견거절-계속기업존속의문시";
    if (opiCode == "50") opiText = "감사미필";
    if (opiCode == "70") opiText = "검토(표준)";
    if (opiCode == "71") opiText = "검토(한정)";
    if (opiCode == "72") opiText = "검토(부적정)";
    if (opiCode == "73") opiText = "검토(의견거절)";
    if (opiCode == "80") opiText = "미검토";
    return opiText;
};


/**
 * 계정코드 변경
 */
scwin.fn_accntCdOpen = async function() {
    await $c.frame.CreateDialogFrame("ACNT", "./ULDFIS00600_P10.gfm", "재무계정검색", 10, 10, 683 + 20, 485 + 40, "window");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_firstSet();
};
scwin.btn_Excel_onclick = function() {
    if (grd_ComList.getTotalRow() <= 0) {
        $c.win.alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_ComList, "요약재무정보", "", "2"); //엑셀 다운로드

};
scwin.btn_Search_onclick = function() {
    scwin.fn_initialize();
    scwin.fn_InspecOp();
};
scwin.img_CoSearch_onclick = function() {
    scwin.fn_ComSrchOpen();
};
scwin.txb_CoSnm_onchange = function() {
    // 조회조건이 변경된 경우 초기화.
    txb_KisCd.setValue("");
    txb_IndPttn.setValue("");
};
scwin.txb_CoSnm_onkeydown = function() {
    // 기업명 키다운.
    if (event.keyCode == 13) {
        $c.frame.focus();
        if ($c.stf.getObjectValue(txb_CoSnm) == "") {
            // 기업검색팝업 오픈
            scwin.fn_ComSrchOpen();
        } else {
            // 기업정보 조회
            scwin.fn_ComInfoSrch();
        }
    }
};
scwin.grd_ComList_OnDblClick = function(row, colid) {
    scwin.fn_OpenDetail(row);
};
scwin.dts_inspecOp_OnLoadCompleted = function(rowcount) {
    if ($c.stf.getObjectValue(cmb_searchType) == '1') {
        searchTypeNM = '구성비';
    } else {
        searchTypeNM = '증감률';
    }
    for (var i = 1; i <= dts_inspecOp.getTotalRow(); i++) {
        var fiscal_typ = dts_inspecOp.getCellData(i, "FISCAL_TYP");
        var fiscal_mm_text = "";
        if (fiscal_typ == 'K') fiscal_mm_text = '온기';

        else if (fiscal_typ == 'T') fiscal_mm_text = '3분기(누적)';

        else if (fiscal_typ == 'B') fiscal_mm_text = '반기';

        else if (fiscal_typ == 'F') fiscal_mm_text = '1분기';

        else if (fiscal_typ == 'X') fiscal_mm_text = '2분기';

        else if (fiscal_typ == 'Y') fiscal_mm_text = '3분기';

        else if (fiscal_typ == 'Z') fiscal_mm_text = '4분기';
        $c.cm.setColumnProp(grd_ComList, i + "date", "Name", dts_inspecOp.getCellData(i, "FISCAL_YYYY") + "년 " + dts_inspecOp.getCellData(i, "FISCAL_MM") + "월 (" + fiscal_mm_text + ")");
        var ISU_ADMIN_YN = (dts_inspecOp.getCellData(i, "ISU_ADMIN_YN") == "Y") ? "관리종목" : "관련없음";
        var AUDT_OPIN_LDIV = dts_inspecOp.getCellData(i, "AUDT_OPIN_LDIV");
        var AUDT_OPIN_MDIV = dts_inspecOp.getCellData(i, "AUDT_OPIN_MDIV");
        $c.cm.setColumnProp(grd_ComList, "inspection" + String(i, scwin.getOpiText(AUDT_OPIN_LDIV + AUDT_OPIN_MDIV) + " / " + ISU_ADMIN_YN), "Name", '');
        $c.cm.setColumnProp(grd_ComList, "data_op" + i + "_1", "Name", "금액");
        $c.cm.setColumnProp(grd_ComList, "data_op" + i + "_2", "Name", searchTypeNM);
    }
    scwin.fn_Search3();
};
scwin.dts_ComList_OnLoadCompleted = function(rowcount) {
    if (dts_ComList.errorMsg) {
        $c.win.alert(dts_ComList.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_ComList);
};
scwin.panel_page_onclick = function() {
    scwin.fn_accntCdOpen();
};
